Before viewing data, let's see what columns each table has: DESCRIBE customers; You will see something like: Field Type Null Key Default Extra id int NO PRI NULL auto_increment first_name varchar(50) NO NULL last_name varchar(50) NO NULL email varchar(100) YES UNI NULL phone varchar(20) YES NULL city varchar(50) YES NULL created_at timestamp YES CURRENT_TIMESTAMP This tells you: Field = column name Type = what kind of data (text, number, date, etc.) Null = can this column be empty? (NO = must have a value) Key = is this a special key? (PRI = primary key, UNI = unique) Try this for other tables too: DESCRIBE products;
DESCRIBE orders;
DESCRIBE order_items;

126.body:
Real databases have multiple tables that connect to each other. Let's create a full school system: -- Students table
CREATE TABLE students ( id INT AUTO_INCREMENT PRIMARY KEY, first_name VARCHAR(50) NOT NULL, last_name VARCHAR(50) NOT NULL, email VARCHAR(100) UNIQUE, birth_date DATE, enrolled_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
); -- Teachers table
CREATE TABLE teachers ( id INT AUTO_INCREMENT PRIMARY KEY, first_name VARCHAR(50) NOT NULL, last_name VARCHAR(50) NOT NULL, subject VARCHAR(100), email VARCHAR(100) UNIQUE
); -- Courses table
CREATE TABLE courses ( id INT AUTO_INCREMENT PRIMARY KEY, course_name VARCHAR(100) NOT NULL, teacher_id INT, max_students INT DEFAULT 30, FOREIGN KEY (teacher_id) REFERENCES teachers(id)
); -- Enrollments table (connects students to courses)
CREATE TABLE enrollments ( id INT AUTO_INCREMENT PRIMARY KEY, student_id INT NOT NULL, course_id INT NOT NULL, grade DECIMAL(5, 2), enrolled_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (student_id) REFERENCES students(id), FOREIGN KEY (course_id) REFERENCES courses(id)
);

