265.body:
-- Equal
SELECT * FROM products WHERE price = 29.99; -- Greater / Less than
SELECT * FROM products WHERE price > 50;
SELECT * FROM products WHERE price <= 30; -- Range
SELECT * FROM products WHERE price BETWEEN 20 AND 60; -- List of values
SELECT * FROM customers WHERE city IN ('New York', 'Chicago', 'Houston'); -- Pattern matching (LIKE)
SELECT * FROM customers WHERE email LIKE 'j%'; -- starts with j
SELECT * FROM products WHERE name LIKE '%Pro%'; -- contains Pro
SELECT * FROM customers WHERE city LIKE '%as'; -- ends with as -- Conditions
SELECT * FROM products WHERE price > 20 AND category = 'Electronics';
SELECT * FROM products WHERE category = 'Books' OR category = 'Sports'; -- NULL check
SELECT * FROM customers WHERE phone IS NULL;
SELECT * FROM customers WHERE phone IS NOT NULL;
